'use strict';
function cableSectionsHTML(edge,prefix){let ss=cableSegments(edge);return `<form class="cable-sections" data-sections-edge="${esc(edge.id)}"><div class="cable-sections-heading"><span>長さ・コメント</span><strong data-sections-total>${cableLengthText(edge.length)} <small>合計 / ${ss.length}本</small></strong><button type="button" data-add-extension ${ss.length>=12?'disabled':''}>＋ 延長</button></div><div class="cable-section-list">${ss.map((s,i)=>`<div class="cable-section-row" data-section-row="${i}" data-section-id="${esc(s.id)}"><span class="section-number">${String(i+1).padStart(2,'0')}</span><label class="section-length">${i?'延長 '+i:'ケーブル 1'}<span><input ${prefix==='inspect'&&i===0?'id="cablelength"':''} data-section-length type="number" min="0.1" max="1000" step="0.1" value="${s.length}" aria-label="${prefix==='inspect'?'詳細：':''}${i?'延長 '+i:'ケーブル 1'}の長さ（m）" required> m</span></label><label class="section-note">コメント<input data-section-note maxlength="120" value="${esc(s.note||'')}" placeholder="例：ステージ側 / 予備" aria-label="${prefix==='inspect'?'詳細：':''}${i?'延長 '+i:'ケーブル 1'}のコメント"></label>${i?`<button type="button" data-remove-extension="${i}" aria-label="延長 ${i} を外す" title="この延長区間を削除">×</button>`:'<span></span>'}</div>`).join('')}</div><p class="cable-sections-hint">変更は自動保存。延長は直列の中継点で表示します。中継コネクター・伝送方式は実機に合わせて用意してください。</p><p class="cable-sections-error" role="status"></p></form>`}
function readCableSections(form){return [...form.querySelectorAll('[data-section-row]')].map(row=>({id:row.dataset.sectionId,length:Number(row.querySelector('[data-section-length]').value),note:row.querySelector('[data-section-note]').value.trim()}))}
function applyCableSections(id,segments,repaint=false,record=true){let edge=state.edges.find(e=>e.id===id);if(!edge)return false;let total=cableSegmentTotal(segments);validateCableSegments({...edge,segments,length:total});if(JSON.stringify(cableSegments(edge))===JSON.stringify(segments))return true;if(record)remember();edge.segments=segments;edge.length=total;if(repaint)render();else{save();wires();cables();updateCableCounts();$('#undo').disabled=!history.length;for(let form of $$('[data-sections-edge]'))if(form.dataset.sectionsEdge===id){let label=form.querySelector('[data-sections-total]');label.innerHTML=`${cableLengthText(total)} <small>合計 / ${segments.length}本</small>`;for(let row of form.querySelectorAll('[data-section-row]')){let s=segments.find(s=>s.id===row.dataset.sectionId);if(!s)continue;let length=row.querySelector('[data-section-length]'),note=row.querySelector('[data-section-note]');if(document.activeElement!==length)length.value=s.length;if(document.activeElement!==note)note.value=s.note||''}}for(let label of $$('[data-route-total]'))label.textContent=cableLabel(edge.type)+' · '+cableLengthText(total)+'（合計）'}return true}
function bindCableSections(root){for(let form of root.querySelectorAll('[data-sections-edge]')){let report=message=>form.querySelector('.cable-sections-error').textContent=message;form.onsubmit=e=>{e.preventDefault();try{applyCableSections(form.dataset.sectionsEdge,readCableSections(form));report('保存しました')}catch(err){report(err.message)}};form.onchange=()=>{try{applyCableSections(form.dataset.sectionsEdge,readCableSections(form));report('保存しました')}catch(err){report(err.message)}};for(let input of form.querySelectorAll('input')){input.onchange=event=>{event.stopPropagation();form.onchange()};input.onfocus=()=>{input.cableRemembered=false};input.oninput=()=>{try{applyCableSections(form.dataset.sectionsEdge,readCableSections(form),false,!input.cableRemembered);input.cableRemembered=true;report('保存しました')}catch{}}};form.querySelector('[data-add-extension]').onclick=()=>{try{let ss=readCableSections(form);if(ss.length>=12)throw Error('延長は最大11本までです');ss.push({id:'s'+Date.now().toString(36)+Math.random().toString(36).slice(2,7),length:3,note:''});applyCableSections(form.dataset.sectionsEdge,ss,true);toast('3mの延長区間を追加しました。長さとコメントを変更できます')}catch(err){report(err.message)}};for(let b of form.querySelectorAll('[data-remove-extension]'))b.onclick=()=>{try{let ss=readCableSections(form);ss.splice(Number(b.dataset.removeExtension),1);applyCableSections(form.dataset.sectionsEdge,ss,true)}catch(err){report(err.message)}}}}
function updateCableCounts(){let all=cableInventory(state.edges).length,shown=cableInventory(state.edges.filter(e=>!isUnified||visibleEdge(e))).length;$('#wirecount').textContent=isUnified?shown+' / '+all:all;$('#navcount').textContent=all}

function positionCableEditor(dock,edge){let frame=$('#canvasframe'),a=point(edge.from,edge.fp),b=point(edge.to,edge.tp),board=$('#board').getBoundingClientRect(),r=frame.getBoundingClientRect(),mid=a&&b?board.left-r.left+(a.x+b.x)/2*zoom:r.width/2;dock.style.left=mid<r.width/2?'auto':'12px';dock.style.right=mid<r.width/2?'12px':'auto'}
